/**
 * SPEC-060: banner de primeros pasos montado en su página (`/captures`) —
 * visibilidad (loading/error/hidden), paso actual y contador derivados,
 * checks fuera de orden, destino de los 8 CTA, persistencia del paso 2,
 * ocultación y retroceso derivado al re-montar. La derivación pura vive en
 * appOnboarding.test.ts y la persistencia en
 * persistence/repository.appOnboarding.test.ts.
 * Generated by QA Dev agent.
 *
 * Frontera de mocking: bridge window.api (installMockApi). La navegación NO se
 * mockea: se observa la location real del MemoryRouter (una sonda), que además
 * verifica el query string de los destinos de Ajustes.
 */
import React from 'react'
import { render, screen, waitFor, within, type RenderResult } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { MemoryRouter, Route, Routes, useLocation } from 'react-router-dom'
import { Toaster } from '@/components/ui/sonner'
import { TooltipProvider } from '@/components/ui/tooltip'
import { CapturesPage } from '@/pages/CapturesPage'
import type { AppOnboardingStatus } from '@/types/domain'
import { installMockApi, type MockApiHandle } from '../../helpers/mockApi'

let mockApi: MockApiHandle

/** Instalación nueva: nada persistido, nada creado, sin claves. */
function status(overrides: Partial<AppOnboardingStatus> = {}): AppOnboardingStatus {
  return {
    settings: { promptsReviewedAt: null, hiddenAt: null },
    hasInterviewTemplate: false,
    hasNoteTemplate: false,
    hasCompany: false,
    hasContact: false,
    hasDiscovery: false,
    hasInterviewGroup: false,
    hasGroupedInterview: false,
    firstCompanyId: null,
    firstDiscoveryId: null,
    firstGroup: null,
    ...overrides
  }
}

/** Configura las DOS fuentes del banner: agregado del almacén + claves. */
function setOnboarding(
  overrides: Partial<AppOnboardingStatus> = {},
  keys: { anthropic?: boolean; deepgram?: boolean } = {}
): void {
  vi.mocked(mockApi.api.db.getOnboardingStatus).mockResolvedValue({
    ok: true,
    data: status(overrides)
  })
  vi.mocked(mockApi.api.secrets.getStatus).mockResolvedValue({
    ok: true,
    data: {
      available: true,
      anthropic: { configured: keys.anthropic ?? false, last4: null },
      deepgram: { configured: keys.deepgram ?? false, last4: null },
      linkedinMcp: { configured: false, last4: null }
    }
  })
}

/** Estado que completa los pasos 2..N del recorrido (los ids ya poblados). */
const COMPLETED: Record<number, Partial<AppOnboardingStatus>> = {
  2: { settings: { promptsReviewedAt: '2026-07-29T08:00:00.000Z', hiddenAt: null } },
  3: { hasInterviewTemplate: true, hasNoteTemplate: true },
  4: { hasCompany: true, firstCompanyId: 'c-1' },
  5: { hasContact: true },
  6: { hasDiscovery: true, firstDiscoveryId: 'd-1' },
  7: { hasInterviewGroup: true, firstGroup: { id: 'g-1', discoveryId: 'd-9' } },
  8: { hasGroupedInterview: true }
}

/** Estado con los pasos 2..step-1 completados (el paso `step` queda actual). */
function upTo(step: number): Partial<AppOnboardingStatus> {
  let merged: Partial<AppOnboardingStatus> = {}
  for (let n = 2; n < step; n += 1) {
    merged = { ...merged, ...COMPLETED[n] }
  }
  return merged
}

/** Sonda de la location real del router (incluye el query string). */
function LocationProbe(): React.ReactElement {
  const location = useLocation()
  return <div data-testid="location">{`${location.pathname}${location.search}`}</div>
}

function renderCaptures(): RenderResult {
  return render(
    <TooltipProvider>
      <MemoryRouter initialEntries={['/captures']}>
        <LocationProbe />
        <Routes>
          <Route path="/captures" element={<CapturesPage />} />
          <Route path="*" element={<div>OTHER_ROUTE_PROBE</div>} />
        </Routes>
      </MemoryRouter>
      <Toaster />
    </TooltipProvider>
  )
}

/** El banner ya resuelto (nunca aparece de forma síncrona). */
async function findBanner(): Promise<HTMLElement> {
  return await screen.findByTestId('app-onboarding-banner')
}

/** Estado visual de cada fila, en orden 1..8. */
function stepStates(banner: HTMLElement): string[] {
  return [1, 2, 3, 4, 5, 6, 7, 8].map(
    (n) => within(banner).getByTestId(`app-onboarding-step-${n}`).getAttribute('data-state') ?? ''
  )
}

beforeEach(() => {
  vi.clearAllMocks()
  mockApi = installMockApi()
})

describe('AppOnboardingBanner en /captures', () => {
  describe('visibilidad y derivación', () => {
    // SPEC-060 · AC-01
    it('shows the banner on a fresh install with step 1 as current and a "0 de 8" counter', async () => {
      setOnboarding()
      renderCaptures()

      const banner = await findBanner()
      expect(within(banner).getByText('Primeros pasos con Maurya')).toBeInTheDocument()
      expect(within(banner).getByText('0 de 8')).toBeInTheDocument()
      expect(stepStates(banner)).toEqual([
        'current',
        'pending',
        'pending',
        'pending',
        'pending',
        'pending',
        'pending',
        'pending'
      ])
      // El paso actual es el único expandido: apoyo + acción primary
      expect(
        within(banner).getByText(
          'Maurya necesita la clave de Claude para generar y la de Deepgram para transcribir.'
        )
      ).toBeInTheDocument()
      expect(within(banner).getByTestId('app-onboarding-action')).toHaveTextContent('Ir a Ajustes')
      // Sin textos de apoyo de los pasos pendientes
      expect(
        within(banner).queryByText(
          'Las entrevistas se organizan por la empresa a la que entrevistas.'
        )
      ).not.toBeInTheDocument()
    })

    // SPEC-060 · AC-02 (sin skeleton ni placeholder mientras el estado no resuelve)
    it('renders nothing at all while the derivation is unresolved', async () => {
      vi.mocked(mockApi.api.db.getOnboardingStatus).mockReturnValue(new Promise<never>(() => {}))
      renderCaptures()

      // La página resuelve por completo…
      expect(await screen.findByText('Aún no hay capturas')).toBeInTheDocument()
      // …y el banner sigue sin pintar nada
      expect(screen.queryByTestId('app-onboarding-banner')).not.toBeInTheDocument()
      expect(screen.queryByText('Primeros pasos con Maurya')).not.toBeInTheDocument()
    })

    // SPEC-060 · AC-03
    it('does not render when hiddenAt is persisted', async () => {
      setOnboarding({ settings: { promptsReviewedAt: null, hiddenAt: '2026-07-29T09:00:00.000Z' } })
      renderCaptures()

      expect(await screen.findByText('Aún no hay capturas')).toBeInTheDocument()
      expect(screen.queryByTestId('app-onboarding-banner')).not.toBeInTheDocument()
    })

    // SPEC-060 · AC-04 (fallo de cualquiera de las dos fuentes → sin banner y
    // con la home intacta; una guía opcional no añade ruido de error)
    it('does not render when either source fails, leaving the page working', async () => {
      setOnboarding()
      vi.mocked(mockApi.api.db.getOnboardingStatus).mockResolvedValue({
        ok: false,
        error: { kind: 'storage', message: 'No se pudo leer el almacén' }
      })
      const first = renderCaptures()

      expect(await screen.findByText('Aún no hay capturas')).toBeInTheDocument()
      expect(screen.queryByTestId('app-onboarding-banner')).not.toBeInTheDocument()
      expect(screen.queryByText('No se pudo leer el almacén')).not.toBeInTheDocument()
      first.unmount()

      setOnboarding()
      vi.mocked(mockApi.api.secrets.getStatus).mockResolvedValue({
        ok: false,
        error: { kind: 'encryption-unavailable', message: 'Cifrado no disponible' }
      })
      renderCaptures()

      expect(await screen.findByText('Aún no hay capturas')).toBeInTheDocument()
      expect(screen.queryByTestId('app-onboarding-banner')).not.toBeInTheDocument()
    })

    // SPEC-060 · AC-05 + AC-22 (8 de 8: estado final con «¡Todo listo!», sin CTA
    // de paso y con «Ocultar» como única acción)
    it('shows the "¡Todo listo!" final state with the 8 checks and only the hide button', async () => {
      setOnboarding({ ...upTo(9), ...COMPLETED[8] }, { anthropic: true, deepgram: true })
      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner)).toEqual(Array<string>(8).fill('done'))
      expect(within(banner).getByText('8 de 8')).toBeInTheDocument()
      expect(
        within(banner).getByText(
          '¡Todo listo! Ya tienes Maurya configurado y tu primera entrevista creada.'
        )
      ).toBeInTheDocument()
      expect(within(banner).queryByTestId('app-onboarding-action')).not.toBeInTheDocument()
      expect(within(banner).getByTestId('app-onboarding-hide')).toHaveTextContent('Ocultar')
    })

    // SPEC-060 · AC-06 (completado fuera de orden: check y contador, sin mover
    // el paso actual)
    it('checks a step completed out of order without moving the current step', async () => {
      setOnboarding(COMPLETED[4])
      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner)).toEqual([
        'current',
        'pending',
        'pending',
        'done',
        'pending',
        'pending',
        'pending',
        'pending'
      ])
      expect(within(banner).getByText('1 de 8')).toBeInTheDocument()
      expect(within(banner).getByTestId('app-onboarding-action')).toHaveTextContent('Ir a Ajustes')
    })
  })

  describe('pasos completados', () => {
    // SPEC-060 · AC-08 (una sola clave no completa el paso 1)
    it('keeps step 1 current when only one key is configured', async () => {
      setOnboarding({}, { anthropic: true })
      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner)[0]).toBe('current')
      expect(within(banner).getByText('0 de 8')).toBeInTheDocument()
    })

    // SPEC-060 · AC-09 (ambas claves → paso 1 con check y paso 2 actual)
    it('completes step 1 with both keys and promotes step 2 to current', async () => {
      setOnboarding({}, { anthropic: true, deepgram: true })

      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner).slice(0, 3)).toEqual(['done', 'current', 'pending'])
      expect(within(banner).getByText('1 de 8')).toBeInTheDocument()
      expect(within(banner).getByTestId('app-onboarding-action')).toHaveTextContent(
        'Revisar prompts'
      )
    })

    // SPEC-060 · AC-11 (la marca persistida completa el paso 2 sin volver a pedir revisión)
    it('shows step 2 as done from the persisted mark without asking for a review again', async () => {
      setOnboarding(upTo(3), { anthropic: true, deepgram: true })
      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner).slice(0, 3)).toEqual(['done', 'done', 'current'])
      expect(within(banner).getByTestId('app-onboarding-action')).toHaveTextContent(
        'Crear plantillas'
      )
      expect(mockApi.api.db.markOnboardingPromptsReviewed).not.toHaveBeenCalled()
    })

    // SPEC-060 · AC-13 (una sola familia de plantillas no completa el paso 3)
    it('keeps step 3 current with interview templates but no note templates', async () => {
      setOnboarding({ ...upTo(3), hasInterviewTemplate: true }, { anthropic: true, deepgram: true })
      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner)[2]).toBe('current')
      expect(within(banner).getByText('2 de 8')).toBeInTheDocument()
    })

    // SPEC-060 · AC-14 + AC-17 (las dos familias completan el paso 3; el
    // contacto completa el paso 5)
    it('completes step 3 with both template families and step 5 with a contact', async () => {
      setOnboarding(upTo(6), { anthropic: true, deepgram: true })
      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner)).toEqual([
        'done',
        'done',
        'done',
        'done',
        'done',
        'current',
        'pending',
        'pending'
      ])
      expect(within(banner).getByText('5 de 8')).toBeInTheDocument()
    })

    // SPEC-060 · AC-21 (una captura —entrevista sin grupo— no completa el paso 8)
    it('keeps step 8 pending when only a group-less capture exists', async () => {
      setOnboarding(upTo(8), { anthropic: true, deepgram: true })
      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner)[7]).toBe('current')
      expect(within(banner).getByText('7 de 8')).toBeInTheDocument()
      expect(
        within(banner).queryByText(
          '¡Todo listo! Ya tienes Maurya configurado y tu primera entrevista creada.'
        )
      ).not.toBeInTheDocument()
    })
  })

  describe('destinos de los CTA', () => {
    const CASES: { step: number; cta: string; target: string; ac: string }[] = [
      { step: 1, cta: 'Ir a Ajustes', target: '/settings?tab=api-keys', ac: 'AC-07' },
      { step: 2, cta: 'Revisar prompts', target: '/settings?tab=custom-prompts', ac: 'AC-10' },
      {
        step: 3,
        cta: 'Crear plantillas',
        target: '/settings?tab=interview-templates',
        ac: 'AC-12'
      },
      { step: 4, cta: 'Crear empresa', target: '/companies', ac: 'AC-15' },
      { step: 5, cta: 'Añadir contacto', target: '/companies/c-1', ac: 'AC-16' },
      { step: 6, cta: 'Crear discovery', target: '/discoveries', ac: 'AC-18' },
      { step: 7, cta: 'Crear grupo', target: '/discoveries/d-1', ac: 'AC-19' },
      { step: 8, cta: 'Crear entrevista', target: '/discoveries/d-9/groups/g-1', ac: 'AC-20' }
    ]

    // SPEC-060 · AC-07/10/12/15/16/18/19/20 (cada CTA navega a su destino)
    it.each(CASES)(
      'navigates from step $step ($ac) with "$cta" to $target',
      async ({ step, cta, target }) => {
        setOnboarding(upTo(step), { anthropic: step > 1, deepgram: step > 1 })
        const user = userEvent.setup()
        renderCaptures()

        const banner = await findBanner()
        const action = within(banner).getByTestId('app-onboarding-action')
        expect(action).toHaveTextContent(cta)

        await user.click(action)

        await waitFor(() => {
          expect(screen.getByTestId('location').textContent).toBe(target)
        })
      }
    )

    // SPEC-060 · AC-13 (con las plantillas de preguntas ya creadas, el CTA del
    // paso 3 apunta a la familia que falta)
    it('retargets the step 3 CTA at the note templates tab when only note templates are missing', async () => {
      setOnboarding({ ...upTo(3), hasInterviewTemplate: true }, { anthropic: true, deepgram: true })
      const user = userEvent.setup()
      renderCaptures()

      const banner = await findBanner()
      await user.click(within(banner).getByTestId('app-onboarding-action'))

      await waitFor(() => {
        expect(screen.getByTestId('location').textContent).toBe('/settings?tab=note-templates')
      })
    })
  })

  describe('marca del paso 2 y ocultación', () => {
    // SPEC-060 · AC-10 (navegar a los prompts ES el gesto de revisión: navega Y persiste)
    it('persists promptsReviewedAt in the same gesture that navigates to the prompts', async () => {
      setOnboarding(upTo(2), { anthropic: true, deepgram: true })
      vi.mocked(mockApi.api.db.markOnboardingPromptsReviewed).mockResolvedValue({
        ok: true,
        data: { promptsReviewedAt: '2026-07-29T09:30:00.000Z', hiddenAt: null }
      })
      const user = userEvent.setup()
      renderCaptures()

      const banner = await findBanner()
      await user.click(within(banner).getByTestId('app-onboarding-action'))

      expect(mockApi.api.db.markOnboardingPromptsReviewed).toHaveBeenCalledTimes(1)
      await waitFor(() => {
        expect(screen.getByTestId('location').textContent).toBe('/settings?tab=custom-prompts')
      })
    })

    // SPEC-060 · AC-24 (ocultar: el banner desaparece y persiste hiddenAt, sin Toast)
    it('hides the banner and persists hiddenAt when "Ocultar" is pressed', async () => {
      setOnboarding()
      vi.mocked(mockApi.api.db.hideAppOnboarding).mockResolvedValue({
        ok: true,
        data: { promptsReviewedAt: null, hiddenAt: '2026-07-29T09:45:00.000Z' }
      })
      const user = userEvent.setup()
      renderCaptures()

      const banner = await findBanner()
      await user.click(within(banner).getByTestId('app-onboarding-hide'))

      await waitFor(() => {
        expect(screen.queryByTestId('app-onboarding-banner')).not.toBeInTheDocument()
      })
      expect(mockApi.api.db.hideAppOnboarding).toHaveBeenCalledTimes(1)
      // La página sigue intacta tras ocultar
      expect(screen.getByText('Aún no hay capturas')).toBeInTheDocument()
    })

    // SPEC-060 · AC-25 (tras ocultar, recargar la app no lo trae de vuelta)
    it('does not bring the banner back when the app reloads after hiding it', async () => {
      setOnboarding()
      vi.mocked(mockApi.api.db.hideAppOnboarding).mockResolvedValue({
        ok: true,
        data: { promptsReviewedAt: null, hiddenAt: '2026-07-29T09:45:00.000Z' }
      })
      const user = userEvent.setup()
      const first = renderCaptures()

      await user.click(within(await findBanner()).getByTestId('app-onboarding-hide'))
      await waitFor(() => {
        expect(screen.queryByTestId('app-onboarding-banner')).not.toBeInTheDocument()
      })
      first.unmount()

      // Recarga: el almacén ya devuelve la marca persistida
      setOnboarding({ settings: { promptsReviewedAt: null, hiddenAt: '2026-07-29T09:45:00.000Z' } })
      renderCaptures()

      expect(await screen.findByText('Aún no hay capturas')).toBeInTheDocument()
      expect(screen.queryByTestId('app-onboarding-banner')).not.toBeInTheDocument()
    })
  })

  // SPEC-060 · AC-23 (el paso NUNCA se persiste: al volver a /captures sin la
  // empresa, el banner retrocede solo)
  describe('retroceso derivado', () => {
    it('walks back to step 4 with steps 4 and 5 unchecked after the last company is deleted', async () => {
      setOnboarding(upTo(6), { anthropic: true, deepgram: true })
      const first = renderCaptures()

      expect(stepStates(await findBanner()).slice(3, 5)).toEqual(['done', 'done'])
      first.unmount()

      // La empresa (y en cascada su contacto) desaparecen del almacén
      setOnboarding(
        { ...upTo(6), hasCompany: false, hasContact: false, firstCompanyId: null },
        { anthropic: true, deepgram: true }
      )
      renderCaptures()

      const banner = await findBanner()
      expect(stepStates(banner)).toEqual([
        'done',
        'done',
        'done',
        'current',
        'pending',
        'pending',
        'pending',
        'pending'
      ])
      expect(within(banner).getByText('3 de 8')).toBeInTheDocument()
      expect(within(banner).getByTestId('app-onboarding-action')).toHaveTextContent('Crear empresa')
    })
  })
})
